"""Help desk helpers for Part 2. (Provided. You do not edit this file.)

A TICKET is a dict:
    'id'        an int, unique; tickets are numbered in the order they arrive
    'arrive'    the minute the ticket arrives (an int, 0 or more)
    'priority'  1, 2 or 3: 1 is urgent, 3 is "whenever you get to it"
    'duration'  how many minutes an agent needs to handle it (an int, 1 or more)

An ESCALATION is a tuple (minute, ticket_id, new_priority): at that minute, if the ticket is
still waiting in the queue, its priority becomes new_priority.

A RECORD, which simulate returns one of for every ticket, is a tuple
(ticket_id, start_minute, agent_number).
"""
import random

PRIORITY_WEIGHTS = {1: 0.2, 2: 0.3, 3: 0.5}


def make_ticket(ticket_id, arrive, priority, duration):
    return {'id': ticket_id, 'arrive': arrive, 'priority': priority, 'duration': duration}


def make_tickets(seed, minutes=480, rate=0.23, shortest=3, longest=15):
    """Return a list of random tickets that arrive during the first `minutes` minutes.

    Each minute, a ticket arrives with probability `rate`. Durations are whole minutes from
    shortest to longest. The same seed always gives the same tickets.
    """
    rng = random.Random(seed)
    tickets = []
    for minute in range(minutes):
        if rng.random() < rate:
            priority = rng.choices([1, 2, 3], weights=[PRIORITY_WEIGHTS[p] for p in (1, 2, 3)])[0]
            duration = rng.randint(shortest, longest)
            tickets.append(make_ticket(len(tickets), minute, priority, duration))
    return tickets


def aging_escalations(tickets, every=30):
    """Return escalations that move each ticket up one priority level for every `every`
    minutes it has waited (3 becomes 2, then 1; a ticket never goes above 1).
    Escalations for tickets that have already started are ignored by simulate."""
    escalations = []
    for t in tickets:
        level = t['priority']
        minute = t['arrive']
        while level > 1:
            minute += every
            level -= 1
            escalations.append((minute, t['id'], level))
    escalations.sort(key=lambda e: (e[0], e[1]))
    return escalations


def waits(tickets, records):
    """Return a dict: ticket id -> minutes it waited before an agent started on it."""
    arrive = {t['id']: t['arrive'] for t in tickets}
    return {ticket_id: start - arrive[ticket_id] for ticket_id, start, _ in records}


def summarize(tickets, records):
    """Return {priority: (count, average wait, longest wait)}, by each ticket's ORIGINAL priority."""
    w = waits(tickets, records)
    out = {}
    for p in (1, 2, 3):
        mine = [w[t['id']] for t in tickets if t['priority'] == p and t['id'] in w]
        if mine:
            out[p] = (len(mine), sum(mine) / len(mine), max(mine))
        else:
            out[p] = (0, 0.0, 0)
    return out
